prime.source:
// The original counter-and-reset algorithm, expressed as source code.
// This deliberately exposes many individual arithmetic and control updates.
fn main(n) {
  if (n < 2) { return 0; }
  let divisor = 2;
  while (divisor < n) {
    let count = 0;
    let remainder = 0;
    while (count < n) {
      count = count + 1;
      remainder = remainder + 1;
      if (remainder == divisor) {
        if (count == n) { return 0; }
        while (remainder > 0) {
          remainder = remainder - 1;
        }
      }
    }
    while (count > 0) {
      count = count - 1;
      remainder = remainder - 1;
    }
    divisor = divisor + 1;
  }
  return 1;
}

factorial.source:
// Genuine source-level self recursion, with 16 fixed activation banks.
// 0! through 12! fit in u32. Larger products fault instead of wrapping.
// Every call, return, addition, and loop becomes ordinary matrix circuitry.
fn multiply(value, times) {
  let product = 0;
  while (times > 0) {
    product = product + value;
    times = times - 1;
  }
  return product;
}

rec fn factorial(n) {
  if (n <= 1) { return 1; }
  let previous = factorial(n - 1);
  return multiply(previous, n);
}

fn main(n) {
  return factorial(n);
}
